{
 "summary": "The main theorem `ehrhart_volume_inequality_for_sets` faithfully states Theorem 1.1: for n ≥ 1, a convex compact set with nonempty interior, barycenter 0 and int(S) ∩ ℤⁿ = {0} has volume ≤ (n+1)ⁿ/n!. The sharpness lemmas are badly mis-stated, and this is the key caveat. `sharpConstant n` is defined as (n+2)ⁿ/n!, but the centered simplex (n+1)Δₙ − 𝟙 has volume (n+1)ⁿ/n!. So `normalizedVolume_centeredSimplex` is false (n=1: length 2 ≠ 3), and `exists_centeredBody_sharp` contradicts the main theorem.",
 "glossary": [
  {"decl": "Ehrhart.Space", "line": 10, "plain": "ℝⁿ as Fin n → ℝ with product Lebesgue measure", "standard_concept": "Euclidean space ℝⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.integerPoint", "line": 12, "plain": "embedding ℤⁿ → ℝⁿ", "standard_concept": "lattice ℤⁿ ⊂ ℝⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.standardSimplex", "line": 15, "plain": "Δₙ = {x ≥ 0, Σxᵢ ≤ 1} = conv{0, e₁, …, eₙ}", "standard_concept": "standard simplex Δₙ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.simplexDilation", "line": 18, "plain": "x ↦ (n+1)x − (1,…,1)", "standard_concept": "affine map defining the centered simplex", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.centeredSimplex", "line": 21, "plain": "(n+1)Δₙ − (1,…,1)", "standard_concept": "centered simplex of the paper", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.normalizedVolume", "line": 24, "plain": "vol(K) as a real number (toReal; an infinite measure would give 0)", "standard_concept": "Lebesgue volume", "matches_standard": "yes", "note": "Harmless on compact sets, which have finite measure."},
  {"decl": "Ehrhart.barycenter", "line": 27, "plain": "vol(K)⁻¹ ∫_K x dx (junk 0 when vol = 0 or the integral is not defined)", "standard_concept": "barycenter", "matches_standard": "yes", "note": "Agrees with the true barycenter for compact K with nonempty interior."},
  {"decl": "Ehrhart.interiorLatticePoints", "line": 30, "plain": "{z ∈ ℤⁿ : z ∈ int K}", "standard_concept": "int(K) ∩ ℤⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.CenteredBody", "line": 33, "plain": "a convex compact K with int K ≠ ∅, barycenter 0 and int K ∩ ℤⁿ = {0}", "standard_concept": "hypothesis class of Theorem 1.1", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.sharpConstant", "line": 41, "plain": "(n+2)ⁿ/n!", "standard_concept": "the sharp constant (n+1)ⁿ/n!", "matches_standard": "no", "note": "Uses n+2 instead of n+1."}
 ],
 "lean_claims": [
  {"theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "line": 48, "plain": "For all n, the barycenter of (n+1)Δₙ − 𝟙 is 0."},
  {"theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "line": 52, "plain": "For n > 0, vol((n+1)Δₙ − 𝟙) = (n+2)ⁿ/n!."},
  {"theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "plain": "For n > 0, there exists a convex compact full-dimensional K with barycenter 0 and int K ∩ ℤⁿ = {0} whose volume is (n+2)ⁿ/n!."},
  {"theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 65, "plain": "For n > 0 and S ⊂ ℝⁿ convex, compact, with int S ≠ ∅, barycenter 0 and int S ∩ ℤⁿ = {0}: vol(S) ≤ (n+1)ⁿ/n!."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "A full-dimensional compact convex K ⊂ ℝⁿ with barycenter 0 and int(K) ∩ ℤⁿ = {0} has vol(K) ≤ (n+1)ⁿ/n!."},
  {"ref": "Theorem 1.1 (sharpness remark)", "plain": "The simplex (n+1)Δₙ − (1,…,1) has barycenter 0, no other interior lattice point, and volume (n+1)ⁿ/n!."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "relation": "equivalent", "why": "All hypotheses and the bound match; n ≥ 1 is implicit in the paper."},
  {"paper_ref": "Theorem 1.1 (sharpness remark)", "lean_theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "relation": "equivalent", "why": "Barycenter-zero part of the sharpness claim."},
  {"paper_ref": "Theorem 1.1 (sharpness remark)", "lean_theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "relation": "different", "why": "Claims volume (n+2)ⁿ/n! instead of (n+1)ⁿ/n!; this is false."},
  {"paper_ref": "Theorem 1.1 (sharpness remark)", "lean_theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "relation": "different", "why": "Asserts a body of volume (n+2)ⁿ/n!, which exceeds the proven bound."}
 ],
 "flags": [
  {"id": "F1", "category": "definition-mismatch", "severity": "high", "decl": "Ehrhart.sharpConstant", "line": 42, "paper_ref": "Theorem 1.1 (sharpness remark)", "explanation": "sharpConstant is (n+2)ⁿ/n!, but the paper's sharp value is (n+1)ⁿ/n!, the volume of the centered simplex. Both sharpness theorems inherit this error.", "polarity": "unclear", "probe_idea": "example : sharpConstant 1 = 3 := by norm_num [sharpConstant]"},
  {"id": "F2", "category": "goal-substitution", "severity": "high", "decl": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "line": 53, "paper_ref": "Theorem 1.1 (sharpness remark)", "explanation": "The centered simplex has volume (n+1)ⁿ·vol(Δₙ) = (n+1)ⁿ/n!. For n=1 it is [-1,1] with length 2, whereas sharpConstant 1 = 3. The statement as written is false, so a genuine proof should be impossible.", "polarity": "lean stronger", "probe_idea": "theorem : normalizedVolume (centeredSimplex 1) = 2  (then 2 ≠ 3 refutes the stated theorem)"},
  {"id": "F3", "category": "goal-substitution", "severity": "high", "decl": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 58, "paper_ref": "Theorem 1.1 (sharpness remark)", "explanation": "Asserts a CenteredBody with volume (n+2)ⁿ/n! > (n+1)ⁿ/n!. This directly contradicts ehrhart_volume_inequality_for_sets. If both are kernel-checked without sorry, something is inconsistent, so the target set needs auditing.", "polarity": "lean stronger", "probe_idea": "example : False := by obtain ⟨K, hK⟩ := exists_centeredBody_sharp 1 one_pos; have := ehrhart_volume_inequality_for_sets one_pos K.carrier K.convex K.compact K.fullDimensional K.centered K.uniqueInteriorLatticePoint; norm_num [sharpConstant] at *; linarith"},
  {"id": "F4", "category": "coverage", "severity": "low", "decl": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "line": 48, "paper_ref": "Theorem 1.1 (sharpness remark)", "explanation": "The claim that the centered simplex has no other interior lattice point is formalized only inside exists_centeredBody_sharp (via the CenteredBody structure), which has the wrong volume.", "polarity": "n/a", "probe_idea": "theorem : interiorLatticePoints (centeredSimplex n) = {0}"}
 ],
 "lint_verdicts": [
  {"line": 28, "rule": "junk-integral", "verdict": "harmless", "why": "Under compactness and nonempty interior, the volume is positive and finite and the identity is integrable on K, so the barycenter is the genuine one."},
  {"line": 42, "rule": "junk-div", "verdict": "harmless", "why": "n! ≠ 0; the real problem with this line is the numerator n+2, not the division (see F1)."},
  {"line": 73, "rule": "junk-div", "verdict": "harmless", "why": "n! > 0, so the division is genuine."}
 ]
